import{_ as e,a as r,o,a2 as a}from"./chunks/framework.DCcmcJcL.js";const l=JSON.parse('{"title":"Attribute Input Types","description":"","frontmatter":{},"headers":[],"relativePath":"attribute/attribute-input.md","filePath":"attribute/attribute-input.md","lastUpdated":1789441803000}'),s={name:"attribute/attribute-input.md"};function n(d,t,i,h,u,c){return o(),r("div",null,t[0]||(t[0]=[a('<h1 id="attribute-input-types" tabindex="-1">Attribute Input Types <a class="header-anchor" href="#attribute-input-types" aria-label="Permalink to &quot;Attribute Input Types&quot;">​</a></h1><p>Every attribute has a type. The type decides what you fill in on the product edit screen, such as a text box, a switch or a list of options, and which settings the attribute can use. You choose the type when you <a href="./product-attribute.html">create the attribute</a>, and you can&#39;t change it afterwards.</p><h2 id="the-types" tabindex="-1">The types <a class="header-anchor" href="#the-types" aria-label="Permalink to &quot;The types&quot;">​</a></h2><p>The <strong>Attribute Type</strong> list offers these types, in this order:</p><table tabindex="0"><thead><tr><th>Type</th><th>On the product edit screen</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Text</strong></td><td>A one-line text box.</td><td>Short values, such as a model number.</td></tr><tr><td><strong>Textarea</strong></td><td>A multi-line text box, or a text editor when <strong>Enable Wysiwyg Editor</strong> is on.</td><td>Longer text, such as care instructions.</td></tr><tr><td><strong>Price</strong></td><td>An amount next to your base currency symbol. It must be a number.</td><td>Extra amounts, such as a recommended retail price.</td></tr><tr><td><strong>Boolean</strong></td><td>A switch that&#39;s on or off.</td><td>Yes-or-no facts, such as whether a jacket is waterproof.</td></tr><tr><td><strong>Checkbox</strong></td><td>One checkbox for each option. You can tick any number of them.</td><td>Features, such as the rooms a lamp suits.</td></tr><tr><td><strong>Select</strong></td><td>A list of options. You pick one.</td><td>Choices such as Color, Size or Brand.</td></tr><tr><td><strong>Multiselect</strong></td><td>A list of options. You pick one or more.</td><td>Several values at once, such as the seasons a jacket suits.</td></tr><tr><td><strong>Date</strong></td><td>A date picker.</td><td>Dates, such as a release date.</td></tr><tr><td><strong>Datetime</strong></td><td>A date and time picker.</td><td>Moments, such as the start of a live event.</td></tr><tr><td><strong>Image</strong></td><td>An image upload in BMP, JPEG, JPG, PNG or WEBP format.</td><td>A picture, such as a size chart.</td></tr><tr><td><strong>File</strong></td><td>A file upload.</td><td>A document, such as a user manual.</td></tr></tbody></table><h2 id="settings-each-type-supports" tabindex="-1">Settings each type supports <a class="header-anchor" href="#settings-each-type-supports" aria-label="Permalink to &quot;Settings each type supports&quot;">​</a></h2><p>Some settings can be used only with certain types. For other types they&#39;re hidden, greyed out, or ignored when you save:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Types</th></tr></thead><tbody><tr><td><strong>Options</strong></td><td>Checkbox, Select and Multiselect. You add the choices yourself.</td></tr><tr><td><strong>Input Options</strong></td><td>Select. The options can show as a dropdown, or as color, image or text swatches.</td></tr><tr><td><strong>Use in Layered Navigation</strong></td><td>Checkbox, Select, Multiselect, Boolean and Price.</td></tr><tr><td><strong>Use To Create Configurable Product</strong></td><td>Select.</td></tr><tr><td><strong>Enable Wysiwyg Editor</strong></td><td>Textarea.</td></tr><tr><td><strong>Default Value</strong></td><td>Boolean.</td></tr><tr><td><strong>Input Validation</strong></td><td>Text.</td></tr><tr><td><strong>Value Per Locale</strong></td><td>Every type except Checkbox, Select, Multiselect and Boolean. Checkbox, Select and Multiselect attributes translate their option names instead, and Boolean attributes show <strong>Yes</strong> or <strong>No</strong>.</td></tr></tbody></table><p>The other settings, such as <strong>Is Required</strong> and <strong>Value Per Channel</strong>, appear for every type. <a href="./product-attribute.html">Product Attributes</a> describes what each setting does.</p><h2 id="what-shoppers-see" tabindex="-1">What shoppers see <a class="header-anchor" href="#what-shoppers-see" aria-label="Permalink to &quot;What shoppers see&quot;">​</a></h2><p>When <strong>Use in Layered Navigation</strong> is on, you can tick the attribute under a category&#39;s <strong>Filterable Attributes</strong>, and it becomes a filter on that category&#39;s page. Search results offer every such attribute as a filter. A <strong>Price</strong> attribute shows as a range slider, and the other types show their options as checkboxes.</p><p>For a <strong>Select</strong> attribute that configurable products use for their variants, <strong>Input Options</strong> decides how shoppers pick a variant on the product page:</p><table tabindex="0"><thead><tr><th>Input Options</th><th>What shoppers see</th></tr></thead><tbody><tr><td><strong>Dropdown</strong></td><td>A drop-down list of the options.</td></tr><tr><td><strong>Color Swatch</strong></td><td>A colored circle for each option.</td></tr><tr><td><strong>Image Swatch</strong></td><td>A small image for each option.</td></tr><tr><td><strong>Text Swatch</strong></td><td>A button with each option&#39;s label.</td></tr></tbody></table><h2 id="upload-size-of-image-and-file-attributes" tabindex="-1">Upload size of Image and File attributes <a class="header-anchor" href="#upload-size-of-image-and-file-attributes" aria-label="Permalink to &quot;Upload size of Image and File attributes&quot;">​</a></h2><p>The largest image or file you can upload for an <strong>Image</strong> or <strong>File</strong> attribute is set under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>. See <a href="./../configure/attribute.html">Attribute</a>.</p>',15)]))}const g=e(s,[["render",n]]);export{l as __pageData,g as default};
